3	
4	/**
5	 * Marketing layout primitives (v2 redesign) — the single reuse layer every page
6	 * is built from, so the whole site reads as one designed thing.
7	 *
8	 *  - <Section>   full-width band with an alternating background "tone" and a
9	 *                consistent vertical rhythm + content rail. Replaces the ad-hoc
10	 *                `mx-auto max-w-6xl px-5 py-20` strings copy-pasted everywhere.
11	 *  - <PageHero>  the standard sub-page hero (eyebrow → title → sub → CTAs +
12	 *                optional visual). Replaces ~10 hand-rolled hero blocks.
13	 *  - <Eyebrow>   the uppercase tag above a heading.
14	 *  - <SectionTitle> heading + optional sub, centered or left.
15	 *
16	 * Colors and animations are the existing brand system (navy + violet/blue).
17	 */
18	
19	type Tone = "base" | "panel" | "deep";
20	type Size = "sm" | "md" | "lg";
21	
22	const TONE: Record<Tone, string> = {
23	  base: "",
24	  panel: "tone-panel",
25	  deep: "tone-deep",
26	};
27	const PAD: Record<Size, string> = {
28	  sm: "py-14 sm:py-16",
29	  md: "py-20 sm:py-24",
30	  lg: "py-24 sm:py-32",
31	};
32	
33	/** A full-width section band. `tone` alternates the background for rhythm. */
34	export function Section({
35	  children,
36	  tone = "base",
37	  size = "md",
38	  id,
39	  className = "",
40	}: {
41	  children: React.ReactNode;
42	  tone?: Tone;
43	  size?: Size;
44	  id?: string;
45	  className?: string;
46	}) {
47	  return (
48	    <section id={id} className={`relative ${TONE[tone]} ${PAD[size]} ${className}`}>
49	      <div className="rail">{children}</div>
50	    </section>
51	  );
52	}
53	
54	/** Uppercase eyebrow tag. `pill` gives it the bordered chip treatment. */
55	export function Eyebrow({ children, pill = false }: { children: React.ReactNode; pill?: boolean }) {
56	  return <span className={pill ? "eyebrow-pill" : "eyebrow"}>{children}</span>;
57	}
58	
59	/** Section heading block: eyebrow + title + optional sub. */
60	export function SectionTitle({
61	  eyebrow,
62	  title,
63	  sub,
64	  align = "center",
65	  className = "",
66	}: {
67	  eyebrow?: string;
68	  title: React.ReactNode;
69	  sub?: React.ReactNode;
70	  align?: "center" | "left";
71	  className?: string;
72	}) {
73	  const alignCls = align === "center" ? "mx-auto text-center" : "text-left";
74	  return (
75	    <div className={`max-w-2xl ${alignCls} ${className}`}>
76	      {eyebrow && <Eyebrow>{eyebrow}</Eyebrow>}
77	      <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl text-balance">{title}</h2>
78	      {sub && <p className="mt-4 text-lg leading-relaxed text-slate-400">{sub}</p>}
79	    </div>
80	  );
81	}
82	
83	type Cta = { label: string; href: string };
84	
85	/**
86	 * Standard sub-page hero. Left-aligned title/sub/CTAs with an optional visual on
87	 * the right; falls back to centered when no visual is supplied. Renders the
88	 * reusable `.hero-aura` glow behind everything.
89	 */
90	export function PageHero({
91	  eyebrow,
92	  title,
93	  highlight,
94	  sub,
95	  primary,
96	  secondary,
97	  visual,
98	  children,
99	}: {
100	  eyebrow?: string;
101	  title: React.ReactNode;
102	  /** Optional trailing fragment rendered in the brand gradient. */
103	  highlight?: string;
104	  sub?: React.ReactNode;
105	  primary?: Cta;
106	  secondary?: Cta;
107	  visual?: React.ReactNode;
108	  children?: React.ReactNode;
109	}) {
110	  const centered = !visual;
111	  return (
112	    <section className="relative overflow-hidden">
113	      <div className="pointer-events-none absolute inset-0 -z-10 hero-aura" aria-hidden />
114	      <div className="rail py-20 sm:py-28">
115	        <div className={centered ? "mx-auto max-w-3xl text-center" : "grid items-center gap-12 lg:grid-cols-2"}>
116	          <Reveal>
117	            {eyebrow && <Eyebrow pill>{eyebrow}</Eyebrow>}
118	            <h1 className="mt-5 text-4xl font-bold leading-[1.08] tracking-tight text-white sm:text-5xl lg:text-6xl text-balance">
119	              {title}
120	              {highlight && (
121	                <>
122	                  {" "}
123	                  <span className="grad-text">{highlight}</span>
124	                </>
125	              )}
126	            </h1>
127	            {sub && (
128	              <p className={`mt-6 text-lg leading-relaxed text-slate-400 sm:text-xl ${centered ? "mx-auto max-w-2xl" : "max-w-xl"}`}>
129	                {sub}
130	              </p>
131	            )}
132	            {(primary || secondary) && (
133	              <div className={`mt-9 flex flex-wrap gap-3 ${centered ? "justify-center" : ""}`}>
134	                {primary && (
135	                  <Link href={primary.href} className="btn-primary px-5 py-3 text-base">
136	                    {primary.label}
137	                  </Link>
138	                )}
139	                {secondary && (
140	                  <Link href={secondary.href} className="btn-secondary px-5 py-3 text-base">
141	                    {secondary.label}
142	                  </Link>
143	                )}
144	              </div>
145	            )}
146	            {children}
147	          </Reveal>
148	          {visual && <Reveal className="lg:pl-6">{visual}</Reveal>}
149	        </div>
150	      </div>
151	    </section>
152	  );
153	}
