3	import { useEffect, useRef, useState } from "react";
4	
5	/**
6	 * Lightweight reveal-on-scroll wrapper. Fades + rises children into view
7	 * the first time they intersect the viewport. CSS-only motion; degrades to
8	 * visible if IntersectionObserver is unavailable.
9	 */
10	export function Reveal({
11	  children,
12	  delay = 0,
13	  className = "",
14	  as: Tag = "div",
15	}: {
16	  children: React.ReactNode;
17	  delay?: number;
18	  className?: string;
19	  as?: React.ElementType;
20	}) {
21	  const ref = useRef<HTMLElement | null>(null);
22	  const [shown, setShown] = useState(false);
23	
24	  useEffect(() => {
25	    const el = ref.current;
26	    if (!el) return;
27	    if (typeof IntersectionObserver === "undefined") {
28	      setShown(true);
29	      return;
30	    }
31	    const io = new IntersectionObserver(
32	      (entries) => {
33	        for (const e of entries) {
34	          if (e.isIntersecting) {
35	            setShown(true);
36	            io.disconnect();
37	          }
38	        }
39	      },
40	      { threshold: 0.12, rootMargin: "0px 0px -40px 0px" },
41	    );
42	    io.observe(el);
43	    return () => io.disconnect();
44	  }, []);
45	
46	  return (
47	    <Tag
48	      ref={ref}
49	      className={`transition-all duration-700 ease-out ${
50	        shown ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"
51	      } ${className}`}
52	      style={{ transitionDelay: `${delay}ms` }}
53	    >
54	      {children}
55	    </Tag>
56	  );
57	}
