import type { Metadata } from "next";
import { Section, SectionTitle, PageHero } from "@/components/marketing/primitives";
import { FeatureCard, CtaBand } from "@/components/marketing/sections";
import { Reveal } from "@/components/marketing/Reveal";
import {
  IconMail,
  IconGlobe,
  IconShield,
  IconClock,
  IconCheck,
  IconArrow,
} from "@/components/marketing/icons";

export const metadata: Metadata = {
  title: "Business Email — Nxeon",
  description:
    "Professional email on your own domain. Real mailboxes with webmail, IMAP/SMTP, spam and virus filtering, and shared calendars — from $1.99/mo.",
};

const WHY = [
  {
    icon: <IconGlobe />,
    title: "Email on your own domain",
    body: "Send and receive as you@yourbrand.com instead of a generic address. Every message reinforces your brand, not someone else's.",
  },
  {
    icon: <IconMail />,
    title: "Webmail + IMAP/SMTP",
    body: "Use the built-in webmail from any browser, or connect Outlook, Apple Mail, Thunderbird, and your phone over standard IMAP and SMTP.",
  },
  {
    icon: <IconShield />,
    title: "Spam & virus filtering",
    body: "Inbound mail is scanned for spam and known malware before it reaches you, so your inbox stays clean and your team stays safe.",
  },
  {
    icon: <IconClock />,
    title: "Calendars & contacts",
    body: "Shared calendars and address books keep everyone in sync — schedule, invite, and stay organised alongside your mail.",
