  {
    name: "Starter",
    price: "$1.99",
    cadence: "/mo",
    tagline: "A professional inbox for you.",
    features: ["1 mailbox", "10 GB storage", "Webmail + IMAP/SMTP", "Spam & virus filtering"],
  },
  {
    name: "Business",
    price: "$7.99",
    cadence: "/mo",
    tagline: "Email for a small team.",
    features: ["5 mailboxes", "25 GB per mailbox", "Shared calendars & contacts", "Spam & virus filtering"],
    popular: true,
  },
  {
    name: "Pro",
    price: "$24.99",
    cadence: "/mo",
    tagline: "Room for the whole company.",
    features: ["25 mailboxes", "50 GB per mailbox", "Shared calendars & contacts", "Priority support"],
  },
];

const SETUP = [
  "Add your domain and we generate the exact records to publish",
  "Set the MX records so mail routes to your mailboxes",
  "Add the SPF record so your outgoing mail is properly identified",
];

function InboxVisual() {
  const rows = [
    { from: "Ava Martins", subj: "Re: Onboarding next steps", time: "9:41" },
    { from: "Billing", subj: "Your July invoice is ready", time: "8:12" },
    { from: "Noah Reyes", subj: "Design review — v2 mockups", time: "Tue" },
    { from: "Support", subj: "Ticket #4821 resolved", time: "Mon" },
  ];
  return (
    <div className="glass p-4 sm:p-5">
      <div className="flex items-center justify-between border-b border-white/[0.06] pb-3">
        <div className="flex items-center gap-2">
          <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-accent-blue/30 to-brand-500/30 text-brand-200">
            <IconMail size={16} />
